import Foundation
import PinkhaKit
import XCTest
@testable import PinkhaHeartEngine

/// Original generated bytes from run 44954793488. These are synthetic account
/// responses produced by the actual native byte entry in two fresh processes.
final class HeartAuthorizedOperationNativeFixtureTests: XCTestCase {
    func testActualGeneratedNativeBytesDecodeAcrossColdReopenAndBlockUnreachability() throws {
        let state = try JSONDecoder().decode(NativeState.self, from: bytes("state.json"))
        let scope = try TorahOperationReadScope(engine: .heart, accountID: state.AccountID,
                                               spaceID: state.SpaceID, sessionGeneration: UUID())
        let createdBytes = try bytes("create-live.pb")
        let reopenedBytes = try bytes("reopen-live.pb")
        XCTAssertEqual(createdBytes, reopenedBytes)
        let live = try HeartAuthorizedOperationCodec.decode(createdBytes, operationID: state.OperationID, scope: scope)
        let reopened = try HeartAuthorizedOperationCodec.decode(reopenedBytes, operationID: state.OperationID, scope: scope)
        let unreachable = try HeartAuthorizedOperationCodec.decode(bytes("reopen-unreachable.pb"), operationID: state.OperationID, scope: scope)
        XCTAssertEqual(live, reopened)
        XCTAssertEqual(live.outcome, .found)
        XCTAssertEqual(live.variants.count, 1)
        XCTAssertFalse(live.conflicted)
        let original = try XCTUnwrap(live.variants.first), orphan = try XCTUnwrap(unreachable.variants.first)
        XCTAssertEqual(original.claimID, state.ClaimID)
        XCTAssertEqual(original.authorID, state.AccountID)
        XCTAssertEqual(original.target, .block(objectId: state.DocumentID, blockId: state.BlockID))
        XCTAssertEqual(original.provenance.first?.nativeChangeID, state.ChangeID)
        XCTAssertEqual(original.reachability, .liveBlock)
        XCTAssertEqual(orphan.reachability, .unreachableBlock)
        XCTAssertEqual(orphan.canonicalBytes, original.canonicalBytes)
        XCTAssertEqual(orphan.claimID, original.claimID)
        XCTAssertEqual(orphan.provenance, original.provenance)
        XCTAssertNotEqual(unreachable.nativeSnapshotToken, live.nativeSnapshotToken)
        // The reopened live response precedes deletion. This fixture does not
        // claim a third process reopened the newly unreachable block state.
    }

    private func bytes(_ name: String) throws -> Data {
#if SWIFT_PACKAGE
        let bundle = Bundle.module
#else
        let bundle = Bundle(for: Self.self)
#endif
        let directory = try XCTUnwrap(bundle.resourceURL).appendingPathComponent("Fixtures/NativeAccount44954793488")
        return try Data(contentsOf: directory.appendingPathComponent(name))
    }

    private struct NativeState: Decodable {
        let AccountID, SpaceID, DocumentID, BlockID, OperationID, ClaimID, ChangeID: String
    }
}
